1112	    // ── P2.5 (GrokAdamW ONLY): GLOBAL grad-norm clip coefficient. Eager
1113	    //    grokadamw clips the WHOLE grad set to grad_clip via a GLOBAL L2 norm
1114	    //    (clip_grad_norms_device_side → total_norm = sqrt(Σ_i ‖g_i‖²),
1115	    //    clip_coef = grad_clip/(total_norm+1e-6) when total_norm>grad_clip,
1116	    //    else 1) BEFORE the apply. We replicate it on the REDUCED grad with a
1117	    //    deterministic ascending reduction (no float atomics): each CTA sums a
1118	    //    contiguous element-range into a per-CTA partial slot, CTA0 sums the
1119	    //    partials in ascending CTA order → total_norm → clip_coef, broadcast via
1120	    //    a workspace slot. The grad buffer is NOT mutated (the return_grad oracle
1121	    //    + the eager-side clip must both see the unclipped reduced grad); the
1122	    //    coefficient is applied per-element inside apply_optimizer<GrokAdamW>.
1123	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
1124	    //    EXTENDED to NeuralGrok: eager neuralgrok applies the SAME global grad-norm
1125	    //    clip (clip_grad_norms_device_side, grad_clip=1.0) before psi+amp — reuse
1126	    //    this exact performant+deterministic machinery (apply_optimizer<NeuralGrok>
1127	    //    consumes st.clip_coef). Every non-{GrokAdamW,NeuralGrok} opt stays byte-identical.
1128	    if constexpr (Opt == OptId::GrokAdamW || Opt == OptId::NeuralGrok) {
1129	        // Reuse the (now-consumed) loss workspace: loss_part[nCTA] holds per-CTA
1130	        // partial sum-of-squares; loss_out (1 float) broadcasts clip_coef. The
1131	        // reduced loss is already in *tok.loss_out (state), so this is free scratch.
1132	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
1133	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
1134	        // Per-CTA contiguous element range over `grad` (the reduced grad, [total]).
1135	        const int64_t total = kDecTotalElems;
1136	        const int64_t base = total / nCTA, rem = total % nCTA;
1137	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
1138	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
1139	        // Thread-local partial → block reduce (fixed tree) → thread0 writes the slot.
1140	        float tsum = 0.0f;
1141	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
1142	            const float gv = grad[e0 + i];
1143	            tsum += gv * gv;
1144	        }
1145	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
1146	        float* red = sm.red;
1147	        red[threadIdx.x] = tsum;
1148	        __syncthreads();
1149	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
1150	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
1151	            __syncthreads();
1152	        }
1153	        if (threadIdx.x == 0) sq_part[cta] = red[0];
1154	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
1155	        // CTA0 ascending-order reduce → total_norm → clip_coef (deterministic).
1156	        if (cta == 0 && threadIdx.x == 0) {
1157	            double ss = 0.0;
1158	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
1159	            const float total_norm = sqrtf((float)ss);
1160	            float coef = 1.0f;
1161	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
1162	                coef = st.grad_clip / (total_norm + 1e-6f);
1163	            *coef_bc = coef;
1164	        }
1165	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
1166	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
