1189	    //    the same values differently and the owner's d can differ at ULP level from
1190	    //    step>=2 (a COMPONENT_CONTRACT deterministic-reduction violation — even where
1191	    //    it happens to be empirically bit-exact on a given GPU/workload, it is not
1192	    //    deterministic BY CONSTRUCTION). GrokAdamW's P2.5 reduces a FIXED contiguous
1193	    //    element range per CTA with a plain sync() and is A/A/A-CLEAN; prodigy now
1194	    //    uses the IDENTICAL shape — deterministic by construction, independent of CTA
1195	    //    timing. Each CTA owns [e0,e0+ecnt) of the FLAT [0,total) arrays —
1196	    //    params/param_init/grad are parallel flat blobs, so a contiguous flat range
1197	    //    sum == the cross-all-TENSORS sum (tensor boundaries are irrelevant to a
1198	    //    global Σ). The per-element contribution still CALLS the canonical
1199	    //    prodigy_partials_step (prodigy.h:28-53, single-source). NO float atomic;
1200	    //    per-CTA (r,s) slot publish → ONE plain grid barrier → CTA0 owner-sums
1201	    //    ascending → EMA-decay/update_d → broadcast → ONE plain grid barrier.
1202	    //    g_next_task is UNTOUCHED here (B2 already reset it to 0), so P3's queue
1203	    //    drain runs unchanged — no sync_reset needed in P2.6.
1204	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
1205	    if constexpr (Opt == OptId::Prodigy) {
1206	        // Per-CTA (r,s) slots in opt_reduce ([r slots | s slots]) + the reduced-d
1207	        // broadcast slot. d_prev: persisted d_lr (slot 2), or d0 cold-start at step 1.
1208	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
1209	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
1210	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
1211	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
1212	        // FIXED contiguous element range over the flat [0,total_p) arrays (same split
1213	        // as GrokAdamW P2.5: even base + remainder to the low CTAs → deterministic).
1214	        const int64_t total_p = kDecTotalElems;
1215	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
1216	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
1217	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
1218	        float r_acc = 0.0f, s_acc = 0.0f;
1219	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
