1254	    //    2D weights (INTEGRATION-OPTSTAGES §3). IDENTICAL to the vit twin
1255	    //    (fused_vit_megakernel.cuh P2.7) — same shared opt_stages_precompute.cuh
1256	    //    helpers, same barrier sequence — only the per-model 2D table (dectc::
1257	    //    kDecMuon2D, 11 matrices including tok[99,128]/pos[4,128]) and offset array
1258	    //    (kDecOffsets) differ. For EACH 2D matrix all CTAs cooperate: buf=μ·buf+g
1259	    //    (buf is the PERSISTENT m-slice — momentum state, NOT transient), ‖buf‖_F via
1260	    //    per-CTA partials → inv_norm, X=buf·inv_norm, then ns_steps × { A=XXᵀ → AX=A·X
1261	    //    → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap }, then the canonical muon_update_step
1262	    //    apply (decay·p + neg_lr_scale·orth). The 1D / non-2D weights (biases, LN γ/β)
1263	    //    take the AdamW aux tail in P3. The elementwise bodies CALL muon.h
1264	    //    (muon_momentum_normalize_step via the phaseA buf body, muon_ns_combine_step,
1265	    //    muon_update_step); the matmuls are the cited new device code (the eager path
1266	    //    delegates to torch::mm/cuBLAS). Guarded so every other opt is byte-identical
1267	    //    (no extra barriers / work).
1268	    if constexpr (Opt == OptId::Muon) {
1269	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
1270	        PrecomputeWorkspace pw{};
1271	        pw.muon_X            = muon_base;
1272	        pw.muon_AX           = pw.muon_X   + dectc::kDecMuonMaxNumel;
1273	        pw.muon_AAX          = pw.muon_AX  + dectc::kDecMuonMaxNumel;
1274	        pw.muon_orth         = pw.muon_AAX + dectc::kDecMuonMaxNumel;
1275	        pw.muon_A            = pw.muon_orth + dectc::kDecMuonMaxNumel;
1276	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows;
1277	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
1278	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
1279	        const int   ns_steps = 5;                 // bindings.cpp default
1280	        for (int mi = 0; mi < dectc::kDecNumMuon2D; ++mi) {
1281	            const dectc::DecMuon2D M = dectc::kDecMuon2D[mi];
1282	            const int rows = M.rows, cols = M.cols;
1283	            const int64_t numel = (int64_t)rows * cols;
1284	            const int64_t off   = (int64_t)kDecOffsets[M.tidx];
1285	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
1286	            pw.muon_buf = st.exp_avg + off;
1287	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
1288	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
1289	            bar.sync();
1290	            muon_norm_reduce_phaseB(ctx, pw);
1291	            bar.sync();
1292	            muon_scale_X(numel, pw);
1293	            bar.sync();
1294	            // NS iterations. After each combine, orth holds the new iterate; swap so
1295	            // the next iteration reads it as X. ns_steps swaps → final result is in
1296	            // muon_X (the last combine wrote muon_orth, then we swapped → muon_X).
1297	            for (int s = 0; s < ns_steps; ++s) {
1298	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
1299	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
1300	                bar.sync();
1301	                // AX = A X   (M=rows,N=cols,K=rows).
1302	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
1303	                bar.sync();
1304	                // AAX = A (AX) (M=rows,N=cols,K=rows).
1305	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
1306	                bar.sync();
1307	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
1308	                bar.sync();
1309	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
1310	            }
1311	            // Apply Muon: p = decay_factor·p + neg_lr_scale·orth  (muon.h:63-73).
1312	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
1313	            const float neg_lr_scale = -lr * scale;
1314	            const float decay_factor = 1.0f - lr * st.wd;
1315	            float* __restrict__ p = params + off;
1316	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
1317	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
1318	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
